<template>
 <section class="raid-loot" aria-label="Récompenses sauvegardées" data-raid-rewards>
  <header><span aria-hidden="true">✧</span><div><small>BUTIN DE LA FAILLE</small><h3>Le fruit de votre victoire</h3></div><strong>+{{ money(reward.money) }} <small>₽</small></strong></header>
  <div class="loot-grid"><article v-for="item in reward.items" :key="item.key" :class="{'is-plate':isPlate(item),'is-rare':item.key==='potential_pearl'}" :style="palette(item)" :data-raid-prize="item.key"><div class="loot-icon"><bag-item-icon :item-key="item.key" :pocket="pocket(item)"/></div><div><small>{{ item.key==='potential_pearl'?'TRÉSOR RARE':isPlate(item)?'PLAQUE · '+typeName(plateType(item)):'RESSOURCE' }}</small><b>{{ item.name }}</b><p v-if="item.key==='potential_pearl'">Un potentiel à révéler · +1 K, jusqu’à K4</p></div><strong class="loot-quantity">×{{ item.quantity }}</strong><span v-if="item.key==='potential_pearl'" class="loot-spark" aria-hidden="true">✦</span></article></div>
  <p class="loot-saved">{{ reward.items.length?'Objets et Pokédollars ajoutés à ton sac.':'Pokédollars ajoutés à ton solde.' }}</p>
 </section>
</template>
<script>
import BagItemIcon from '../menu/BagItemIcon.vue';
import {localizeTypeName,typeBadgeStyle} from '@/services/pokemonTypes';
export default{components:{BagItemIcon},props:{reward:{type:Object,required:true}},methods:{money:n=>Number(n||0).toLocaleString('fr-FR'),typeName:localizeTypeName,isPlate:item=>item.key.startsWith('dark_plate_'),plateType(item){const t=item.key.replace('dark_plate_','');return t[0]?.toUpperCase()+t.slice(1);},pocket(item){return item.key==='potential_pearl'?'medicine':this.isPlate(item)?'corruption':'treasures';},palette(item){return{'--loot-color':this.isPlate(item)?typeBadgeStyle(this.plateType(item))['--pokemon-type-color']:item.key==='potential_pearl'?'#b699dc':'#8bafbd'};}}};
</script>
